--
-- Table structure for table `performances`
--

DROP TABLE IF EXISTS `performances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `performances` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `show_id` bigint(20) unsigned NOT NULL,
  `room_id` bigint(20) unsigned DEFAULT NULL,
  `starts_at` datetime NOT NULL,
  `auditorium` varchar(80) NOT NULL,
  `format` varchar(40) NOT NULL,
  `language` varchar(60) NOT NULL,
  `unit_price` decimal(10,2) NOT NULL,
  `capacity` smallint(5) unsigned NOT NULL DEFAULT 120,
  `seats_booked` smallint(5) unsigned NOT NULL DEFAULT 0,
  `status` enum('scheduled','cancelled') NOT NULL DEFAULT 'scheduled',
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `cancellation_reason` varchar(255) DEFAULT NULL,
  `history_deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_performance_slot` (`show_id`,`starts_at`,`auditorium`),
  KEY `idx_performances_start` (`starts_at`),
  KEY `idx_performances_show` (`show_id`),
  KEY `fk_performances_room` (`room_id`),
  KEY `idx_performances_history_deleted` (`history_deleted_at`),
  CONSTRAINT `fk_performance_show` FOREIGN KEY (`show_id`) REFERENCES `shows` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_performances_room` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=250 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

